head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > sortable]<br/>Header Column 을 클릭 또는 더블 클릭하여 데이터를 정렬할지 설정합니다.",
    "validation" : [
        "sortable=true 면 Header Column 클릭 또는 더블클릭하여 데이터를 정렬할 수 있어야 합니다.",
        "sortable=false(기본값)면 Header Column 클릭 또는 더블클릭해도 데이터가 정렬되지 않아야 합니다.(다중 정렬은 Ctrl + 더블클릭으로 수행)",
        "2 개 이상의 Column 으로 다중 정렬 시 정렬 순번이 아이콘 옆에 숫자로 표시되어야 합니다.",
        "정렬 가능한 Header Column 에 'w2grid_head_sortable' 클래스가 추가되어야 합니다.",
        "Header Column 의 개별 sortable 속성을 설정한 경우 해당 Column 은 GridView 컴포넌트의 sortable 속성이 무시되고, 개별 sortable 속성이 설정되지 않은 경우 GridView 컴포넌트의 sortable 속성이 적용되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con_sortable : 공통 gdl_boolean 바인딩 → getText() 로 label('' / 'true' / 'false') 판단
    //  - '' 미설정(기본 false) / 'true' / 'false'
    let vSortable = con_sortable.getText();

    // GridView 컴포넌트 자체의 sortable 설정
    //  + 정렬 아이콘/w2grid_head_sortable 클래스 확인을 위해 showSortableImage=true 항상 포함
    let properties = {
        showSortableImage: true,
    };

    // sortable : 미설정('') 이면 속성 자체를 추가하지 않음(기본 false)
    if (vSortable === 'true') {
        properties.sortable = true;
    } else if (vSortable === 'false') {
        properties.sortable = false;
    }

    let lblDesc = 'GridView sortable=' + (vSortable === '' ? '(미설정)' : vSortable)
        + ', showSortableImage=true / column1 은 개별 sortable=false 설정(GridView sortable 무시), column2~4 는 개별 미설정(GridView sortable 적용)';

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // dataList 생성 (5행, col1~col4)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 5);

    // 개별 sortable 속성을 가진 커스텀 gridView 생성 (@spec1 검증)
    //  - column1 : sortable="false" 개별 설정 → GridView sortable=true 여도 정렬 불가
    //  - column2~4 : 개별 sortable 미설정 → GridView sortable 설정을 그대로 적용
    await scwin.createSortableGridView(cList);
}



// 개별 sortable 설정을 섞은 gridView 동적 생성 (마지막 컬럼 width="*", 가로 스크롤 방지)
//  (createBasicGridView 는 컬럼별 sortable 미지원 → 인라인 구성으로 @spec1 충족)
scwin.createSortableGridView = async function (cList) {
    let grp_comp = document.querySelector('.tc_group_basic');
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" dataList="data:dlt_bind" style="width:500px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="120" style="" inputType="text" id="column1" value="col1" sortable="false"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 정렬 상태 확인 :
//  각 Header th 별로 w2grid_head_sortable 클래스 보유 여부(정렬 가능 표시 = @propval/@spec1 적용 결과)와
//  현재 다중정렬 순번 숫자(2개 이상 정렬 시 아이콘 옆 숫자) 표시 여부를 출력.
//  (정렬 자체는 사용자가 Header 를 클릭/더블클릭하여 수행 → 정렬 트리거 버튼은 생성하지 않음)
scwin.btn_checkSortable_onclick = function (e) {
    let headTable = document.querySelector("[id*='target1_head_table']");
    if (!headTable) {
        wf_body_bottom.getObj("scwin").setReturnValue("head_table 를 찾을 수 없습니다.");
        return;
    }

    wf_body_bottom.getObj("scwin").setReturnValue("[GridView sortable 옵션] : " + target1.options.sortable);

    // 데이터 컬럼 헤더 th 들만 대상 (행번호/상태 컬럼 제외 위해 column 클래스 보유 th 선택)
    let ths = headTable.querySelectorAll("th[class*='_header__column']");
    for (let i = 0; i < ths.length; i++) {
        let th = ths[i];

        // 정렬 가능 표시 클래스
        let hasSortable = th.classList.contains("w2grid_head_sortable");

        // 다중정렬 순번 숫자 : 2개 이상 Column 정렬 시 정렬 아이콘 옆에 표시되는 순번 숫자
        //  엔진은 정렬 아이콘 영역(div[class*='sort_div_sub'])에 순번 텍스트를 출력함
        //  (컬럼 헤더 라벨의 숫자와 혼동되지 않도록 정렬 아이콘 영역 텍스트만 확인)
        let sortSub = th.querySelector("[class*='sort_div_sub']");
        let subText = sortSub ? (sortSub.textContent || "").trim() : "";
        let subNumMatch = subText.match(/\d+/);
        let sortNum = subNumMatch ? subNumMatch[0] : "(없음)";

        wf_body_bottom.getObj("scwin").setReturnValue("Header[" + i + "] (" + th.id.replace(/.*target1_/, "") + ") w2grid_head_sortable 클래스 : " + hasSortable + " / 다중정렬 순번 숫자 : " + sortNum);
    }
}
